INSERT OR IGNORE INTO providers (id, slug, name, tagline, about, brand_color, logo_path, logo_bg, years_label, owner_public_name, team_label, service_area, area_short, regions, services, service_tags, claims, policies, pricing_text, deals, price_label, price_value, card_note, rating, review_count, rating_source, rating_checked_on, internal_phone, internal_email, website_url, internal_notes, status, listed, sort_rank, created_at, updated_at)
  VALUES ('PRV-0001', 'roses-cleaning', 'Rose''s Cleaning Inc', 'Family- and woman-owned cleaning and organizing, run by Rose Santa Rita since 2008.', 'Rose started cleaning homes in 2006 and has owned the business since 2008. The company avoids "cleaning by the numbers" in favor of custom, hands-on service, and gives free estimates in person or by FaceTime or WhatsApp video. They also do professional organizing, and are registered to work on federal properties.', '#f3722b', '/images/providers/roses-cleaning/logo.svg', '#1f2937', '18 yrs in business', 'Rose Santa Rita', 'Multiple crews', 'Boston area, South Shore and Cape Cod', 'Boston · Quincy · South Shore', '["core","south"]', '["Home cleaning","Move-in / move-out","Post-construction","Professional organizing","Carpet & upholstery","Office & commercial"]', '["Move in / out","Post-construction"]', '["Licensed and insured in MA","Woman-owned","Free walkthrough or video estimates"]', '["Fully licensed and insured in Massachusetts (as stated)","Free estimates in person or by video call","Eco-friendly products","Family-owned and woman-owned"]', 'Not published. Free in-person or video estimates.', '[]', 'Pricing', 'Free estimate', 'Owner-run since 2008', 4.7, 57, 'Google', '', '', '', '', '', 'prospect', 0, 10, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');

INSERT OR IGNORE INTO providers (id, slug, name, tagline, about, brand_color, logo_path, logo_bg, years_label, owner_public_name, team_label, service_area, area_short, regions, services, service_tags, claims, policies, pricing_text, deals, price_label, price_value, card_note, rating, review_count, rating_source, rating_checked_on, internal_phone, internal_email, website_url, internal_notes, status, listed, sort_rank, created_at, updated_at)
  VALUES ('PRV-0002', 'sonias-cleaning-services', 'Sonia''s Cleaning Services', 'The cleaning service you don''t have to supervise. Same cleaner every visit, cleaning since 2002.', 'Owner Sonia Vasconcelos has been cleaning homes since 2002. Recurring clients get the same cleaner each visit with no contract, and if anything is missed, the team comes back for a free re-clean when it is reported within 24 hours. Regular cleans are a flat price per visit based on home size and how often; deep, move and post-construction cleans are billed by the hour.', '#461f5c', '/images/providers/sonias-cleaning-services/logo.svg', '#ffffff', 'Cleaning since 2002', 'Sonia Vasconcelos', 'Background-checked team', 'Newton, Chestnut Hill, Brookline, Wellesley, Needham, Belmont, Dedham, plus MetroWest', 'Newton · Brookline · Wellesley', '["west"]', '["Recurring house cleaning","Deep / spring cleaning","Move-in / move-out","Post-construction","Airbnb turnovers","Office & small business"]', '["Recurring","Deep clean","Move in / out","Post-construction","Airbnb"]', '["Bonded, licensed and insured","Background-checked team","Free re-clean guarantee"]', '["Bonded, licensed and insured (as stated)","Free re-clean if reported within 24 hours","Same cleaner every visit","No contracts, change or cancel anytime","Eco-friendly, pet- and child-safe products"]', 'Flat price per visit for regular cleans and Airbnb turnovers. Hourly for deep, move and post-construction cleans. Recurring visits are discounted, and estimates are free.', '[]', 'Pricing', 'Flat rate per visit', 'Bonded & insured', 5, 47, 'Google', '', '', '', '', '', 'prospect', 0, 20, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');

INSERT OR IGNORE INTO providers (id, slug, name, tagline, about, brand_color, logo_path, logo_bg, years_label, owner_public_name, team_label, service_area, area_short, regions, services, service_tags, claims, policies, pricing_text, deals, price_label, price_value, card_note, rating, review_count, rating_source, rating_checked_on, internal_phone, internal_email, website_url, internal_notes, status, listed, sort_rank, created_at, updated_at)
  VALUES ('PRV-0003', 'taskforce-cleaning-services', 'Taskforce Cleaning Services', 'Recurring house cleaning from a vetted crew, with more than 16,000 cleanings done.', 'Taskforce is an Everett-based company focused on high-quality recurring house cleaning. It reports more than 14 years of experience and over 16,000 cleanings. Technicians are vetted when hired, and the company holds IICRC cleaning-technician certification, a Nextdoor Neighborhood Faves listing and a Cleaning for a Reason partnership.', '#1f3c88', '/images/providers/taskforce-cleaning-services/logo.png', '#ffffff', '14+ yrs experience', '', '', 'Everett, Malden, Melrose, Medford, Somerville, Cambridge, Arlington, Lexington, Boston, Revere, Woburn', 'Everett · Somerville · Cambridge', '["core","north"]', '["Recurring (weekly, biweekly, monthly)","Deep cleaning","Move-in / move-out","One-time cleaning","Post-construction","Office & commercial","Disinfecting"]', '["Recurring","Deep clean","Move in / out","Post-construction"]', '["Fully insured","IICRC certified","Satisfaction guaranteed"]', '["Fully insured (as stated)","Technicians vetted when hired","Satisfaction guaranteed","IICRC certified cleaning technician","Cleaning for a Reason partner"]', 'No base prices published. Current offers:', '["25% off the first deep clean with 6 months of recurring service","Up to $100 off: $50 off a deep clean, then $25 off each of the next two cleans"]', 'Current offer', '25% off first deep clean', 'IICRC certified', 5, 67, 'Google', '', '', '', '', '', 'prospect', 0, 30, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');

INSERT OR IGNORE INTO providers (id, slug, name, tagline, about, brand_color, logo_path, logo_bg, years_label, owner_public_name, team_label, service_area, area_short, regions, services, service_tags, claims, policies, pricing_text, deals, price_label, price_value, card_note, rating, review_count, rating_source, rating_checked_on, internal_phone, internal_email, website_url, internal_notes, status, listed, sort_rank, created_at, updated_at)
  VALUES ('PRV-0004', 'moro-pro-cleaning', 'Moro Pro Cleaning', 'A cleaner home and more time for yourself. Melrose-based, serving Greater Boston and the North Shore.', 'Moro Pro Cleaning is based in Melrose. Customers can see an instant price and book online, with no contracts and easy rescheduling, and pay after the clean is finished. The company says it has more than 130 five-star reviews across Google and Thumbtack.', '#3a7dbf', '/images/providers/moro-pro-cleaning/logo.png', '#ffffff', '', '', '', 'Melrose, Medford, Cambridge, Boston, North Shore', 'Melrose · Medford · Cambridge', '["core","north"]', '["Standard cleaning","Deep cleaning","Move-in / move-out","Airbnb & vacation rentals","Post-construction","Commercial"]', '["Recurring","Deep clean","Move in / out","Post-construction","Airbnb"]', '["Licensed and fully insured","Satisfaction guaranteed","No contracts"]', '["Licensed and fully insured (as stated)","Background-checked cleaners (per their FAQ)","Satisfaction guaranteed","No contracts, easy rescheduling","Pay after the clean"]', 'They show instant prices online through a calculator. Ask if Serve can show their starting prices here.', '[]', 'Pricing', 'Instant price online', 'Satisfaction guaranteed', 4.8, 41, 'Google', '', '', '', '', '', 'prospect', 0, 40, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');

