  VALUES ('PRV-0005', '247-cleaning-boston', '247 Cleaning Boston', 'Detail-focused home cleaning with the same trusted team every visit.', '247 Cleaning Boston cleans homes and businesses across Greater Boston with eco-conscious products. The "247" stands for their commitment, not their hours. Reviews describe Carlos as the main contact, who texts ahead to confirm every appointment, and the team will use your own products if you ask.', '#0082fb', '/images/providers/247-cleaning-boston/logo.png', '#ffffff', '', 'Carlos Duarte', '', 'Boston, Arlington and Greater Boston', 'Boston · Arlington', '["core"]', '["Regular cleaning (weekly, biweekly, monthly)","Deep cleaning","Move-in / move-out","Post-construction","Commercial"]', '["Recurring","Deep clean","Move in / out","Post-construction"]', '["Fully insured","Same team every visit","Eco-friendly products"]', '["Fully insured (as stated)","The same team every visit","Eco-friendly products, or yours on request","Texts to confirm every appointment"]', 'Not published. Free quotes.', '[]', 'Pricing', 'Free quote', 'Fully insured', 5, 40, 'Google', '', '', '', '', '', 'prospect', 0, 50, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');

