  VALUES ('PRV-0006', 'cambridge-clean-co', 'Cambridge Clean Co', 'Locally owned, family-run home cleaning for Cambridge and nearby towns, backed by a free re-clean guarantee.', 'Cambridge Clean Co is a family-owned cleaning company based on Concord Avenue in Cambridge. Clients can book online, and every cleaner is interviewed, identity-checked and background- and reference-checked before joining the team. Customer reviews name the owner, Rich Porter, as their main contact.', '#0ca9bb', '/images/providers/cambridge-clean-co/logo.png', '#0ca9bb', '', 'Richard Porter', '', 'Cambridge, Somerville, Arlington, Boston, Belmont, Brookline', 'Cambridge · Somerville · Arlington', '["core"]', '["Recurring cleaning","Deep cleaning","Move-in / move-out","Apartments & condos","Commercial & janitorial"]', '["Recurring","Deep clean","Move in / out"]', '["Background-checked cleaners","Satisfaction guarantee","Family-owned"]', '["100% satisfaction guarantee: free re-clean if you are unhappy","Cleaners are background-, reference- and ID-checked","Pet-friendly technicians","Book online"]', 'Not published. They quote online or after a call.', '[]', 'Pricing', 'Book online', 'Re-clean guarantee', 5, 82, 'Google', '', '', '', '', '', 'prospect', 0, 60, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');

