  VALUES ('PRV-0007', 'jma-cleaning-services', 'JMA Cleaning Services', 'Reliable, insured, detail-oriented cleaning for homes and businesses in Somerville and Boston.', 'JMA Cleaning Service works in Boston and Somerville with trained teams focused on "efficiency, safety, and consistent quality." They offer recurring or one-time home cleans, post-construction cleanups and office cleaning, and promise transparent pricing with clear estimates. Quotes are by phone or WhatsApp, and their site is in English and Portuguese.', '#1fb5c1', '/images/providers/jma-cleaning-services/logo.jpg', '#000000', '', '', '', 'Somerville, Boston', 'Somerville · Boston', '["core"]', '["Recurring cleaning","One-time cleaning","Post-construction","Office & commercial"]', '["Recurring","Post-construction"]', '["Insured staff","Background-checked teams","Clear written estimates"]', '["Insured staff (as stated)","Background-checked teams","Flexible scheduling","Transparent pricing and clear estimates"]', 'Not published. Estimates by phone or WhatsApp.', '[]', 'Pricing', 'Free estimate', 'Background-checked', 5, 43, 'Google', '', '', '', '', '', 'prospect', 0, 70, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');

INSERT OR IGNORE INTO providers (id, slug, name, tagline, about, brand_color, logo_path, logo_bg, years_label, owner_public_name, team_label, service_area, area_short, regions, services, service_tags, claims, policies, pricing_text, deals, price_label, price_value, card_note, rating, review_count, rating_source, rating_checked_on, internal_phone, internal_email, website_url, internal_notes, status, listed, sort_rank, created_at, updated_at)
  VALUES ('PRV-0008', 'pam-cleaning-services', 'Pam Cleaning Services', 'Fully insured house and office cleaning across Greater Boston, trusted since 2020.', 'Pam Cleaning has cleaned Greater Boston homes and offices since 2020. Recurring plans have no contract and can be cancelled anytime, and you pay after each clean, with no deposit or card needed. They use eco-friendly products chosen to cut down on harsh chemicals and strong fumes. A typical clean takes 2 to 3 hours.', '#d9577a', '/images/providers/pam-cleaning-services/logo.png', '#ffffff', '6 yrs in business', 'Pam', '', 'Waltham, Watertown, Newton, Needham, Milton, Medford, plus Boston, Cambridge, Somerville, Brookline', 'Waltham · Newton · Medford', '["core","west","north"]', '["Recurring (weekly, biweekly, monthly)","Deep cleaning","Move-in / move-out","Post-construction","Student dorms & apartments","Commercial"]', '["Recurring","Deep clean","Move in / out","Post-construction"]', '["Fully insured","No contracts","Eco-friendly products"]', '["Fully insured with liability coverage (as stated)","No contracts, cancel anytime","Pay after each clean: cash, check, Venmo or Zelle","Eco-friendly products"]', 'No dollar prices published. Recurring plans are discounted:', '["Weekly: 20% off","Every 2 weeks: 15% off","Monthly: 10% off","Refer a friend: you both save $20"]', 'Recurring plans', 'Up to 20% off', 'Fully insured', 5, 76, 'Google', '', '', '', '', '', 'prospect', 0, 80, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');

