  VALUES ('PRV-0010', 'enis-cleaning', 'Enis Cleaning', 'Home cleaning and maid service across Metro Boston, from a team that started in Boston.', 'Enis Cleaning started in Boston "with a passion for providing cleaning service and healthy home environments" and has since expanded to New York City. Its experienced cleaners handle house cleaning, maid service and business cleaning, with free quotes. Regular hours are 8 AM to 6 PM, and other times can be arranged.', '#3f9a3a', '/images/providers/enis-cleaning/logo.jpg', '#ffffff', '', 'Eni Carneiro', '', 'Metro Boston, including Medford, Brookline, Needham, Wellesley', 'Medford · Brookline · Needham', '["core","north","west"]', '["House cleaning","Maid service","Commercial cleaning"]', '[]', '["Free quotes","Residential and commercial","Based in Medford"]', '["Free quotes","Hours 8 AM to 6 PM, other times by arrangement","Also operates in New York City"]', 'Not published. Newsletter subscribers get 10% off the first clean.', '[]', 'New clients', '10% off first clean', 'Free quotes', 4.9, 523, 'Google', '', '', '', '', '', 'prospect', 0, 100, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');

