  VALUES ('PRV-0011', 'maria-by-house-cleaning', 'Maria By House Cleaning', 'Chelsea-based home and office cleaning, with customer service as the first priority.', 'Maria By House Cleaning is based on Broadway in Chelsea and says customer service is its number one priority. The team does regular, deep and move-in/move-out cleans for apartments and homes, plus offices, clinics and post-construction cleanups. They use steam for carpets, polishing, and products described as safe for families and pets.', '#8b1a1a', '/images/providers/maria-by-house-cleaning/logo.png', '#ffffff', '8 yrs experience', '', '', 'Chelsea, Boston', 'Chelsea · Boston', '["core","north"]', '["Regular cleaning","Deep cleaning","Apartment cleaning","Monthly recurring","Move-in / move-out","Construction cleanup","Office & clinic"]', '["Recurring","Deep clean","Move in / out","Post-construction"]', '["Free estimates","Pet-safe products","Steam cleaning"]', '["Free estimates","Products safe for families and pets","Steam cleaning for carpets","Reach them by WhatsApp"]', 'Not published. Free estimates.', '[]', 'Pricing', 'Free estimate', 'Pet-safe products', 4.9, 48, 'Google', '', '', '', '', '', 'prospect', 0, 110, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');

INSERT OR IGNORE INTO providers (id, slug, name, tagline, about, brand_color, logo_path, logo_bg, years_label, owner_public_name, team_label, service_area, area_short, regions, services, service_tags, claims, policies, pricing_text, deals, price_label, price_value, card_note, rating, review_count, rating_source, rating_checked_on, internal_phone, internal_email, website_url, internal_notes, status, listed, sort_rank, created_at, updated_at)
  VALUES ('PRV-0012', 'taty-cleaning-services', 'Taty Cleaning Services', 'Quincy-based home and office cleaning, with same-day or next-day availability.', 'Taty Cleaning Services is a Quincy company cleaning homes and businesses across Greater Boston. Their "vetted team" handles weekly, biweekly and monthly cleans, deep and move-in/move-out cleans, Airbnb turnovers and post-construction work. You can book online or ask for a free quote, often for the same or next day.', '#1f6fc5', '/images/providers/taty-cleaning-services/logo.png', '#ffffff', '', '', '', 'Quincy, Boston, South Shore', 'Quincy · Boston', '["core","south"]', '["Recurring cleaning","Deep cleaning","Move-in / move-out","Airbnb & rentals","Post-construction","Custom plans","Commercial"]', '["Recurring","Deep clean","Move in / out","Post-construction","Airbnb"]', '["Vetted team","Eco-friendly products","Book online"]', '["Vetted cleaning team","Eco-friendly results","Same-day or next-day availability","Online booking and free quotes"]', 'Not published. Free quotes.', '[]', 'Pricing', 'Free quote', 'Book online', 5, 45, 'Google', '', '', '', '', '', 'prospect', 0, 120, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');

