  VALUES ('PRV-0013', 'luminos-cleaning-services', 'Luminos Cleaning Services', 'A family cleaning company serving the South Shore with natural, pet-friendly products.', 'Luminos is a family business with more than eight years of experience cleaning homes and businesses on the South Shore. They mainly use non-toxic, hypoallergenic, pet-friendly products and use stronger ones only when needed. They say they stick to the quoted price unless you change the job.', '#1e5ba8', '/images/providers/luminos-cleaning-services/logo.png', '#ffffff', '8+ yrs experience', '', 'Family team', 'Quincy, Braintree, Weymouth, Hingham, Hull, Cohasset, Scituate, Norwell, Hanover, Marshfield, Randolph', 'Quincy · Braintree · Hingham', '["south"]', '["House & apartment cleaning","Deep cleaning","Move-in / move-out","Construction cleanup","Commercial","After-party cleaning"]', '["Deep clean","Move in / out","Post-construction"]', '["Family business","Pet-friendly products","Sticks to the quoted price"]', '["Sticks to the quoted price unless the job changes","Non-toxic, hypoallergenic, pet-friendly products","Free quotes by phone or online"]', 'Not published. Free quotes.', '[]', 'Pricing', 'Free quote', 'Keeps the quoted price', 5, 88, 'Google', '', '', '', '', '', 'prospect', 0, 130, '2026-11-07T02:00:14.994Z', '2026-11-07T02:00:14.994Z');
